test('shows only the shared page header', () => {
  const screen = render(
    <ThemeContext.Provider value={mockTheme}>
      <ConsultScreen />
    </ThemeContext.Provider>
  );

  const page = screen.getByTestId('consult-screen');
  const header = screen.UNSAFE_getByType('MockAppPageHeader');

  expect(StyleSheet.flatten(page.props.style)).toMatchObject({
    flex: 1,
    width: '100%',
    paddingHorizontal: 0,
    alignItems: 'stretch',
    backgroundColor: APP_PAGE_BACKGROUND_COLOR,
    borderWidth: 3,
  });
  expect(header.props.titleKey).toBe('consult_page_title');
  expect(screen.queryByTestId('consult-appointment-list')).toBeNull();
  expect(screen.queryByTestId('consult-filter-all')).toBeNull();
  expect(screen.queryByTestId('consult-filter-upcoming')).toBeNull();
  expect(screen.queryByTestId('consult-filter-completed')).toBeNull();
  expect(screen.queryByTestId('consult-hero-placeholder')).toBeNull();
});

